using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.Collections.Generic;using System.Threading;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class MechanismTests {
  static int checks;static void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}static void Near(double a,double b,string name){Check(Math.Abs(a-b)<=1e-7*Math.Max(1,Math.Abs(b)),name+": "+a+" != "+b);}
  static void Ready(WpfScene scene){var watch=System.Diagnostics.Stopwatch.StartNew();while(!scene.Ready&&scene.Error==null&&watch.Elapsed.TotalSeconds<30){Application.DoEvents();Thread.Sleep(10);}Check(scene.Ready,"3D scene ready: "+scene.Error);}
  public static int Run(string folder){Directory.CreateDirectory(folder);var log=new StringBuilder();try{
   var p=MechanismProject.Example(false);var shafts=p.Parts.Where(x=>x.Kind=="shaft").ToArray();var r=MechanismSolver.Solve(p);Check(r.Valid,"single pair valid");Near(r.Shafts[shafts[1].Id].Rpm,-100,"300 -> -100 rpm");Near(r.Shafts[shafts[1].Id].AvailableTorque,5.82,"available torque with efficiency");Near(r.RequiredTorque,3/(3*.97),"load reflected to input");Near(r.Meshes[0].TangentialForce,2000*r.RequiredTorque/40,"tooth force N using mm diameter");Near(r.RequiredPower,3*100*Math.PI/30/.97,"power balance");Check(!r.Overloaded,"load within capacity");log.AppendLine("PASS single pair: n=-100 rpm, capacity=5.82 Nm, reflected load, Ft/Fr and power balance.");
   p.InputRpm=-300;r=MechanismSolver.Solve(p);Near(r.Shafts[shafts[1].Id].Rpm,100,"reverse direction");p.InputRpm=0;r=MechanismSolver.Solve(p);Near(r.RequiredTorque,3/(3*.97),"zero rpm torque balance");Near(r.RequiredPower,0,"zero rpm power");p.InputRpm=300;shafts[1].LoadTorque=0;r=MechanismSolver.Solve(p);Near(r.RequiredTorque,0,"unloaded input demand");Near(r.Meshes[0].TangentialForce,0,"unloaded mesh force");Check(r.Meshes[0].CapacityForce>0,"unloaded capacity kept separate");
   p=MechanismProject.Example(true);r=MechanismSolver.Solve(p);Check(r.Valid,"compound valid");var output=p.Parts.Last(x=>x.Kind=="shaft");Near(r.Shafts[output.Id].Rpm,50,"compound rpm 6:1");Near(r.Shafts[output.Id].AvailableTorque,2*6*.97*.97,"compound output capacity");Near(r.RequiredTorque,5/(6*.97*.97),"compound reflected load");StepExport.Write(MechanismCad.Build(p),Path.Combine(folder,"compound-6.step"));p.Save(Path.Combine(folder,"compound-6.mechanism.json"));log.AppendLine("PASS compound 6:1, both efficiencies and output direction.");
   p=MechanismProject.Example(false);shafts=p.Parts.Where(x=>x.Kind=="shaft").ToArray();shafts[1].LoadTorque=3;var branch=p.Add("shaft");branch.Name="Вторая нагрузка";branch.LoadTorque=3;var g=p.Add("gear");g.ShaftId=branch.Id;g.OffsetZ=10;g.Teeth=60;g.Module=2;p.Links.Add(new MechanismLink{FromId=p.Links[0].FromId,ToId=g.Id,PlacementAngle=180});MechanismCad.AutoArrange(p);r=MechanismSolver.Solve(p);Check(r.Valid&&r.Overloaded,"parallel loads must sum, cannot duplicate input capacity");Near(r.RequiredTorque,6/(3*.97),"branch demand sum");p.InputTorque=3;r=MechanismSolver.Solve(p);Check(!r.Overloaded,"branch input increased");log.AppendLine("PASS branch power/torque conservation; overload with two loads and recovery.");
   p=MechanismProject.Example(false);shafts=p.Parts.Where(x=>x.Kind=="shaft").ToArray();p.DriveShaftId=shafts[1].Id;shafts[1].LoadTorque=0;shafts[0].LoadTorque=.4;r=MechanismSolver.Solve(p);Check(r.Valid,"reverse root solve");Near(r.Shafts[shafts[0].Id].Rpm,-900,"drive from previously driven shaft");Near(r.RequiredTorque,.4*3/.97,"reverse reflected load and efficiency");var loose=p.Add("shaft");r=MechanismSolver.Solve(p);Check(!r.Shafts[loose.Id].Connected,"disconnected shaft not assigned fictional speed");p.InputTorque=double.NaN;Check(MechanismCad.Validate(p).Count>0,"nonfinite input rejected");
   p=MechanismProject.Example(false);p.Links.Add(new MechanismLink{FromId=p.Links[0].FromId,ToId=p.Links[0].ToId});Check(!MechanismSolver.Solve(p).Valid,"indeterminate torque loop rejected");p=MechanismProject.Example(false);p.Find(p.Links[0].ToId).Module=3;Check(!MechanismSolver.Solve(p).Valid,"different modules rejected");p=MechanismProject.Example(false);p.Parts.First(x=>x.Kind=="shaft"&&x.Id!=p.DriveShaftId).X+=5;Check(!MechanismSolver.Solve(p).Valid,"displaced mesh rejected");MechanismCad.AutoArrange(p);Check(MechanismSolver.Solve(p).Valid,"mesh auto arrangement recovers");
   p=new MechanismProject{Name="Ремень 3:1"};var a=p.Add("shaft");var b=p.Add("shaft");var pa=p.Add("pulley");pa.ShaftId=a.Id;pa.OffsetZ=10;pa.Diameter=30;var pb=p.Add("pulley");pb.ShaftId=b.Id;pb.OffsetZ=10;pb.Diameter=90;b.LoadTorque=3;p.Links.Add(new MechanismLink{FromId=pa.Id,ToId=pb.Id,Kind="belt",Efficiency=.9});MechanismCad.AutoArrange(p);r=MechanismSolver.Solve(p);Check(r.Valid,"belt valid");Near(r.Shafts[b.Id].Rpm,100,"open belt same direction");Near(r.Shafts[b.Id].AvailableTorque,5.4,"belt torque");StepExport.Write(MechanismCad.Build(p),Path.Combine(folder,"belt-3.step"));p.Save(Path.Combine(folder,"belt-3.mechanism.json"));
   p=MechanismProject.Example(false);var input=p.Find(p.DriveShaftId);input.Steps.Add(new MechanismStep{Length=20,Diameter=10});input.Steps.Add(new MechanismStep{Length=60,Diameter=16});var block=p.Add("block");block.Name="Плита со сквозным отверстием и карманом";block.X=-60;block.Y=-50;block.SizeX=50;block.SizeY=40;block.Length=12;block.Holes.Add(new MechanismHole{Diameter=6});block.Holes.Add(new MechanismHole{X=12,Diameter=4,Depth=4});var sketch=p.Add("sketch");sketch.X=10;sketch.Y=-60;sketch.Length=10;sketch.Outline.AddRange(new[]{new MechanismPoint(0,0),new MechanismPoint(30,0),new MechanismPoint(30,20),new MechanismPoint(10,30),new MechanismPoint(0,20)});sketch.Holes.Add(new MechanismHole{X=10,Y=10,Diameter=2,Depth=3});var assembly=MechanismCad.Build(p);Check(assembly.Valid,"CAD with shaft steps, blind pockets and sketch: "+string.Join(";",assembly.Errors));Near(assembly.Parts.Single(x=>x.Id==block.Id).Volume(),24000-124*Math.PI,"blind pocket volume");foreach(var part in assembly.Parts){var mesh=PrintExport.Mesh(part);Check(mesh.SignedVolume()>0,"positive closed mesh "+part.Label);Check(Math.Abs(mesh.SignedVolume()/part.Volume()-1)<.015,"mesh agrees with parametric volume "+part.Label);}StepExport.Write(assembly,Path.Combine(folder,"cad-features.step"));p.Save(Path.Combine(folder,"cad-features.mechanism.json"));
   string json=p.Serialize();var restored=MechanismProject.Parse(json);Check(restored.Serialize()==json,"project roundtrip");var oldModel=MechanismCad.Build(restored);Near(oldModel.Parts.Sum(x=>x.Volume()),assembly.Parts.Sum(x=>x.Volume()),"roundtrip geometry");var linked=restored.Parts.First(x=>x.Kind=="gear");string removedShaft=linked.ShaftId;var xyz=restored.Position(linked);restored.Remove(removedShaft);Check(restored.Find(linked.Id).ShaftId==null,"deleting shaft detaches attached geometry");Near(restored.Position(restored.Find(linked.Id))[0],xyz[0],"detached geometry world position preserved");Check(!MechanismCad.SimplePolygon(new[]{new PointF(0,0),new PointF(20,20),new PointF(0,20),new PointF(20,0)}),"self intersecting sketch rejected");block.Holes.Add(new MechanismHole{X=0,Y=0,Diameter=3});Check(!MechanismCad.Build(p).Valid,"overlapping holes blocked");log.AppendLine("PASS CAD: stepped shaft, extruded sketch, through hole, blind pocket, mesh volume, persistence, detach, invalid geometry rejection.");
   using(var sketchDialog=new MechanismSketchDialog(new[]{new MechanismPoint(0,0),new MechanismPoint(10,0),new MechanismPoint(0,10)})){sketchDialog.Show();Application.DoEvents();Check(sketchDialog.Points.Count==3,"sketch editor instantiated");sketchDialog.Close();}
   using(var form=new MechanismForm()){form.Show();Application.DoEvents();form.SetProject(MechanismProject.Example(true));Ready(form.Scene);Check(form.Scene.Nodes.Count==7,"constructor scene component count");var shaft=form.Project.Find(form.Project.DriveShaftId);form.SelectPart(shaft.Id);form.Scene.SetMoveMode(true);Check(form.Scene.BeginPartDrag(shaft.Id,new System.Windows.Point(100,100)),"constructor shaft drag begins");form.Scene.SetOffset(shaft.Id,new Vector3D(5,7,2));form.Scene.EndPartDrag(false);Application.DoEvents();Ready(form.Scene);Near(form.Project.Find(shaft.Id).X,5,"drag X persisted in document");Near(form.Project.Find(shaft.Id).Y,7,"drag Y persisted in document");Near(form.Project.Find(shaft.Id).Z,2,"drag Z persisted in document");MechanismCad.AutoArrange(form.Project);form.SetProject(form.Project);Ready(form.Scene);form.SelectPart(form.Project.Parts.First(q=>q.Kind=="gear").Id);double oldWidth=form.Scene.Root.ActualWidth,oldHeight=form.Scene.Root.ActualHeight;form.Scene.Root.Measure(new System.Windows.Size(1100,750));form.Scene.Root.Arrange(new System.Windows.Rect(0,0,1100,750));form.Scene.SavePng(Path.Combine(folder,"constructor-3d.png"),1100,750);form.Scene.Root.Measure(new System.Windows.Size(oldWidth,oldHeight));form.Scene.Root.Arrange(new System.Windows.Rect(0,0,oldWidth,oldHeight));form.Scene.Fit();Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));bitmap.Save(Path.Combine(folder,"constructor-ui.png"));}form.ApproveTestClose();form.Close();}
   log.AppendLine("PASS native UI: new document, parameter panel, scene, persisted mouse placement, sample and render.");log.AppendLine("PASS "+checks+" mechanism assertions.");File.WriteAllText(Path.Combine(folder,"mechanism-results.txt"),log.ToString(),Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"mechanism-error.txt"),log+Environment.NewLine+ex,Encoding.UTF8);return 1;}}
 }
}
